export interface CreateCrossHostReviewHandlersOptions {
  /** Injectable Codex process seam so the smoke can pass a fake (no real CLI). */
  codexRunner?: CodexReviewRunner;
  managedRunner?: HostRunRunner;
  launchWorker?: ManagedHostRunWorkerLauncher;
  /** Internal smoke seam for adversarial git-race coverage; never exposed through the CLI. */
  afterHeadCaptured?: () => void | Promise<void>;
  /** Internal smoke seam for final write-window race coverage; never exposed through the CLI. */
  beforeVerdictRecord?: () => void | Promise<void>;
  /** Internal smoke seam for post-write cleanup coverage; never exposed through the CLI. */
  afterVerdictPairWritten?: () => void | Promise<void>;
}

async function runManagedCodexReview(
  ctx: HandlerContext,
  opts: {
    storyId: string;
    phase: string;
    storyWorktree: string;
    prompt: string;
    timeoutMs: number;
    environment: NodeJS.ProcessEnv;
    managedRunId?: string;
    detach?: boolean;
  },
  options: CreateCrossHostReviewHandlersOptions,
): Promise<CodexReviewRunnerResult & { managedRunId: string; managedReceiptId: string }> {
  const injectedOutcome: { value: CodexReviewRunnerResult | null } = { value: null };
  const managedRunner: HostRunRunner | undefined = options.managedRunner ?? (options.codexRunner
    ? async plan => {
      const outcome = await options.codexRunner!({
        prompt: plan.stdinText ?? '',
        storyWorktree: opts.storyWorktree,
        timeoutMs: opts.timeoutMs,
        env: opts.environment,
      });
      injectedOutcome.value = outcome;
      if (outcome.stdout) plan.onChunk?.({ stream: 'stdout', text: outcome.stdout });
      return {
        stdout: outcome.stdout,
        stderr: '',
        exitCode: outcome.exitCode ?? 1,
        timedOut: outcome.timedOut,
        timeoutKind: outcome.timedOut ? 'total_timeout' : null,
        terminalReason: outcome.timedOut ? 'total_timeout' : outcome.exitCode === 0 ? 'completed' : 'exit_nonzero',
      };
    }
    : undefined);
  const injectedLauncher: ManagedHostRunWorkerLauncher | undefined = managedRunner
    ? async request => {
      void runManagedHostRunWorker(request, { runner: managedRunner, env: process.env });
      return { pid: process.pid };
    }
    : undefined;
  let submitted;
  if (opts.managedRunId) {
    const binding = readManagedHostRunBinding(ctx.root, opts.managedRunId);
    const expectedPromptDigest = `sha256:${createHash('sha256').update(opts.prompt, 'utf8').digest('hex')}`;
    if (
      binding.host !== 'codex'
      || binding.storyId !== opts.storyId
      || binding.phase !== opts.phase
      || binding.agentType !== 'cross-host-review:codex'
      || binding.profile !== 'cross_host_review_codex'
      || binding.cwd !== opts.storyWorktree
      || binding.projectRootHash !== projectRootHashFor(ctx.root)
      || binding.promptDigest !== expectedPromptDigest
      || binding.timeoutMs > opts.timeoutMs
    ) {
      throw new Error('cross_host_review: managedRunId binding does not match the current story/policy/snapshot/prompt; refusing to resume or spawn a replacement');
    }
    submitted = (await getManagedHostRunStatus({ root: ctx.root, runId: opts.managedRunId })).run;
  } else {
    submitted = await submitManagedHostRun({
      root: ctx.root,
      cwd: opts.storyWorktree,
      host: 'codex',
      storyId: opts.storyId,
      phase: opts.phase,
      agentType: 'cross-host-review:codex',
      promptText: opts.prompt,
      timeoutMs: opts.timeoutMs,
      deadlineMs: opts.timeoutMs,
      projectRootHash: projectRootHashFor(ctx.root),
      profile: 'cross_host_review_codex',
      environment: opts.environment,
    }, { launchWorker: options.launchWorker ?? injectedLauncher });
    ctx.store.appendProcessEvent(opts.storyId, {
      type: 'cross_host_review_managed_submitted',
      storyId: opts.storyId,
      managedRunId: submitted.runId,
      deadlineAt: submitted.deadlineAt,
      timestamp: new Date().toISOString(),
    });
    if (opts.detach) {
      throw new CrossHostReviewDetached({
        schemaVersion: 'lattice.cross_host_review_managed_submission.v1',
        storyId: opts.storyId,
        managedRunId: submitted.runId,
        state: submitted.state,
        deadlineAt: submitted.deadlineAt,
      });
    }
  }
  let run = submitted;
  while (!run.terminal) {
    const status = await getManagedHostRunStatus({
      root: ctx.root,
      runId: run.runId,
      afterGeneration: run.generation,
      waitMs: 30_000,
    });
    run = status.run;
  }
  const stdoutChunks: string[] = [];
  let afterSequence = 0;
  let outputTruncated = false;
  let hasMore = true;
  while (hasMore) {
    const output = readManagedHostRunOutput({ root: ctx.root, runId: run.runId, afterSequence });
    afterSequence = output.nextSequence;
    hasMore = output.hasMore;
    outputTruncated ||= output.truncated;
    for (const frame of output.frames) {
      if (frame.stream === 'stdout') stdoutChunks.push(frame.text);
    }
  }
  const rawStdout = stdoutChunks.join('');
  const maxBytes = 8 * 1024 * 1024;
  const stdout = rawStdout.slice(0, maxBytes);
  const result = readManagedHostRunResult(ctx.root, run.runId);
  const receipt = managedHostRunReceipt(ctx.root, run.runId);
  if (!run.terminal?.replacementSafe
    || run.terminal.processCleanup?.reaped !== true
    || run.terminal.processCleanup.residualProcessGroup) {
    // B-137a:F-114 — carry the runId on the error. This throw happens BEFORE the
    // `return { ... managedRunId }` below, so on a FRESH run (no --managedRunId) the
    // caller's `managedRunId` would still be '' when its finally block computes
    // `cleanupRunId = requestedManagedRunId || managedRunId`. That falsy value took
    // the ternary's else-branch, set resumeCleanupSafe = true, and force-removed the
    // snapshot worktree while this very terminal says the provider process group may
    // still be live — defeating resumedManagedRunAllowsSnapshotCleanup, which exists
    // precisely to prevent that. Tagging the error lets the caller resolve the real
    // runId and re-consult that guard instead of assuming cleanup is safe.
    const unsafeTerminalError = new Error('cross_host_review: managed provider terminal is not replacement-safe/reaped or retains a residual process group; refusing verdict consumption');
    (unsafeTerminalError as Error & { managedRunId?: string }).managedRunId = run.runId;
    throw unsafeTerminalError;
  }
  const terminalExitCode = run.state === 'completed'
    ? result?.exitCode ?? 0
    : result?.exitCode && result.exitCode !== 0
      ? result.exitCode
      : run.state === 'timed_out'
        ? 124
        : 1;
  return {
    stdout,
    stdoutDigest: injectedOutcome.value?.stdoutDigest ?? createHash('sha256').update(rawStdout, 'utf8').digest('hex'),
    exitCode: terminalExitCode,
    timedOut: run.state === 'timed_out' || result?.timedOut === true,
    truncated: injectedOutcome.value?.truncated === true || outputTruncated || rawStdout.length > maxBytes,
    managedRunId: run.runId,
    managedReceiptId: receipt.receiptId,
  };
}

interface CrossHostVerdictDraft {
  storyId: string;
  runId: string;
  hostId: string;
  provider: 'claude' | 'codex';
  sessionId: string;
  keyId: string;
  decision: VerdictDecision;
  materialDigest: string;
  storyFilesHash: string;
  validationDigest: string;
  promptDigest: string;
  receiptId?: string;
  note: string;
}

function buildLocalHostVerdict(draft: CrossHostVerdictDraft, issuedAt: string): HostVerdict {
  const base = {
    schemaVersion: 'lattice.host_verdict.v1' as const,
    mode: 'local' as const,
    storyId: draft.storyId,
    runId: draft.runId,
    hostId: draft.hostId,
    provider: draft.provider,
    sessionId: draft.sessionId,
    keyId: draft.keyId,
    decision: draft.decision,
    materialDigest: draft.materialDigest,
    storyFilesHash: draft.storyFilesHash,
    validationDigest: draft.validationDigest,
    promptDigest: draft.promptDigest,
    ...(draft.receiptId ? { receiptId: draft.receiptId } : {}),
    issuedAt,
    note: draft.note,
  };
  return {
    ...base,
    verdictId: `verdict-${canonicalDigest(base).slice(0, 16)}`,
  };
}

function writeCrossHostVerdictPair(
  ctx: HandlerContext,
  storyId: string,
  hostAVerdict: HostVerdict,
  hostBVerdict: HostVerdict,
): void {
  const dir = join(ctx.root, LATTICE_DIR, 'autopilot-verdicts', storyId);
  mkdirSync(dir, { recursive: true });
  const paths = [
    join(dir, `${hostAVerdict.verdictId}.json`),
    join(dir, `${hostBVerdict.verdictId}.json`),
  ];
  try {
    writeFileSync(paths[0], JSON.stringify(hostAVerdict, null, 2) + '\n', 'utf8');
    writeFileSync(paths[1], JSON.stringify(hostBVerdict, null, 2) + '\n', 'utf8');
  } catch (err) {
    for (const path of paths) rmSync(path, { force: true });
    throw err;
  }
}

function deleteCrossHostVerdictPair(ctx: HandlerContext, storyId: string, ...verdicts: HostVerdict[]): void {
  const dir = join(ctx.root, LATTICE_DIR, 'autopilot-verdicts', storyId);
  for (const verdict of verdicts) {
    rmSync(join(dir, `${verdict.verdictId}.json`), { force: true });
        try {
          promptText = readFileSync(promptFilePath, 'utf8');
        } catch (err) {
          throw new Error(`host_run: cannot read --promptFile "${promptFilePath}": ${err instanceof Error ? err.message : String(err)}`);
        }
      } else {
        promptText = args.prompt as string;
      }
      if (promptText.length === 0) {
        throw new Error('host_run: prompt is empty; refuse pre-spawn');
      }

      // Defense in depth (core enforces this too): a reviewRunId must belong to
      // --storyId so a ledger row cannot silently mis-join across stories.
      if (reviewRunId && storyId && !reviewRunId.startsWith(`${storyId}:`)) {
        throw new Error(
          `host_run: reviewRunId "${reviewRunId}" does not belong to story "${storyId}" ` +
          `(a reviewRunId must be "<storyId>:..."); refuse pre-spawn`,
        );
      }
      const json = wantsJson(args);

      // F-005: resolve story phase + existence through the CONFIGURED store, so a
      // project that configures storyDir is honored (the core stays path-free). An
      // explicit --phase never reaches this (the core skips the store entirely).
      const resolveStory: HostRunStoryResolver = (id: string) => {
        try {
          const story = ctx.store.readStory(id);
          const p = typeof story.phase === 'string' && story.phase.length > 0 ? story.phase : null;
          return { phase: p };
        } catch {
          return null; // unknown story per the configured store
        }
      };

      const explicitPhase = normalizeString(args.phase);
      let phase = explicitPhase || 'adhoc';
      if (!explicitPhase && storyId) {
        const story = resolveStory(storyId);
        if (!story) throw new Error(`host_run: unknown story "${storyId}"; refuse pre-spawn`);
        phase = story.phase || 'adhoc';
      }
      const injectedLauncher: ManagedHostRunWorkerLauncher | undefined = options.runner
        ? async request => {
          void runManagedHostRunWorker(request, { runner: options.runner, env: process.env })
            .catch(() => { /* worker persists its own terminal error where possible */ });
          return { pid: process.pid };
        }
        : undefined;
      const submitted = await submitManagedHostRun(
        {
          host,
          storyId,
          agentType,
          phase,
          promptText,
          reviewRunId,
          lane,
          timeoutMs,
          deadlineMs: deadlineMs ?? timeoutMs,
          cwd: ctx.root,
          root: ctx.root,
          projectRootHash: projectRootHashFor(ctx.root),
          ...(formalReviewBinding ? { profile: 'managed_reviewer', reviewBinding: formalReviewBinding } : {}),
        },
        { launchWorker: options.launchWorker ?? injectedLauncher },
      );
      // Publish the durable identity before either detach returns or foreground
      // attach begins. If the caller disappears while attached, a replacement
      // controller can recover the same worker-owned run through host_run_status
      // instead of launching a duplicate provider.
      ctx.log?.(
        `[host_run] submitted runId=${submitted.runId} state=${submitted.state} `
        + `deadlineAt=${submitted.deadlineAt} attach=${args.detach === true ? 'detached' : 'foreground'}`,
      );
      if (args.detach === true) {
        return { schemaVersion: 'lattice.host_run.v2', detached: true, run: submitted };
      }

      // F-006 / F-008 / F-020: live passthrough. text mode routes host
      // stdout->stdout / stderr->stderr; json mode routes EVERYTHING to stderr so
      // stdout stays clean for the JSON result.
      // F-008: a SYNCHRONOUS write failure is normalized and thrown to the CORE
      // guard, which flips its passthrough-broken flag: delivery stops, the run
      // still completes, and result.passthroughError surfaces the failure honestly.
      // F-020: a real EPIPE (the downstream pipe closed) usually surfaces NOT as a
      // synchronous throw but as an ASYNCHRONOUS 'error' event on process.stdout /
      // process.stderr, which the try/catch below cannot see. The 'error' listeners
      // attached for the duration of the run (below) record the first such failure
      // into `asyncStreamError`; the sink checks it and throws-through so the SAME
      // core passthrough-broken flag flips (delivery stops instead of hammering a
      // dead pipe), and the handler also merges it into the surfaced
      // passthroughError as a backstop for an error that lands after the last chunk.
      let asyncStreamError: string | null = null;
      // F-020 / F-024: track a broken STDOUT and STDERR specifically. Any chunk or
      // diagnostic write issued to a stream we already KNOW is broken would queue an
      // async EPIPE 'error' that can fire AFTER the per-call listener is removed
      // (zero listeners -> process crash). We skip those writes instead — honest
      // degradation, since passthroughError already records the failure.
      let stdoutBroken = false;
      let stderrBroken = false;

      // F-020: contain ASYNC stream 'error' events (real EPIPE) for the DURATION of
      // the run. Node terminates the process only when a stream has ZERO 'error'
      // listeners, so simply attaching ours is sufficient containment: we swallow
      // the error and record the first message. Hygiene: exactly our two named
      // listeners are added below and removed with removeListener in the finally
      // — never removeAllListeners, since other code may hold its own listeners on
      // these shared streams. F-024: a write error surfaced through a write CALLBACK
      // folds into the SAME state, so a late EPIPE reported via callback and one
      // reported via the 'error' event are handled identically.
      const recordStreamError = (streamName: 'stdout' | 'stderr') => (err: unknown): void => {
        if (streamName === 'stderr') stderrBroken = true;
        else stdoutBroken = true;
        if (asyncStreamError === null) {
          const message = err instanceof Error ? err.message : String(err);
          asyncStreamError = `host_run passthrough ${streamName} stream error: ${message}`;
        }
      };
      const onStdoutError = recordStreamError('stdout');
      const onStderrError = recordStreamError('stderr');

      // F-024: outstanding-write accounting for the live passthrough AND the final
      // diagnostics, WITHOUT serializing throughput. Every write below is issued as
      // write(text, cb) and is NOT awaited per-chunk; the callback decrements a
      // shared pending counter. drainPending() — awaited by the finally BEFORE the
      // error listeners are removed — resolves once every in-flight write has
      // settled, so a late EPIPE from the FINAL chunk(s) fires while our named
      // 'error' listeners are still attached. This closes the residual window that
      // F-020/F-023 left on fire-and-forget live passthrough writes.
      let pendingWrites = 0;
      let onDrained: (() => void) | null = null;
      const settleWrite = (): void => {
        pendingWrites -= 1;
        if (pendingWrites <= 0) {
          pendingWrites = 0;
          if (onDrained) {
            const notify = onDrained;
            onDrained = null;
            notify();
          }
        }
      };
      // Defensive cap: a genuinely WEDGED stream (a write that neither flushes nor
      // errors) must never hang host_run. On timeout we mark both streams broken and
      // proceed with listener removal; the ONLY regression is that, for such a
      // pathologically wedged stream, we revert to the pre-fix crash window (a
      // post-removal EPIPE could still be unhandled). Every real closed/broken pipe
      // settles its write callback (with or without error) well within this cap, so
      // in practice drainPending resolves as soon as the last chunk's EPIPE lands.
      const DRAIN_CAP_MS = 2000;
      const drainPending = (): Promise<void> => {
        if (pendingWrites <= 0) return Promise.resolve();
        return new Promise<void>((resolve) => {
          let settled = false;
          const timer = setTimeout(() => {
            if (settled) return;
            settled = true;
            onDrained = null;
            stdoutBroken = true;
            stderrBroken = true;
            resolve();
          }, DRAIN_CAP_MS);
          if (typeof timer.unref === 'function') timer.unref();
          onDrained = () => {
            if (settled) return;
            settled = true;
            clearTimeout(timer);
            resolve();
          };
        });
      };

      // F-006 / F-008 / F-020 / F-024: live passthrough. text mode routes host
      // stdout->stdout / stderr->stderr; json mode routes EVERYTHING to stderr so
      // stdout stays clean for the JSON result. Each chunk write is settle-aware
      // (write + counted callback) but NOT awaited, so throughput is never
      // serialized. A SYNCHRONOUS write failure is still thrown through to the CORE
      // guard (F-008: delivery stops, the run still completes, passthroughError
      // surfaces); an ASYNCHRONOUS 'error' recorded via the callback/listener flips
      // asyncStreamError so the NEXT chunk throws through instead of hammering a dead
      // pipe (F-020).
      const passthrough: HostRunPassthrough = (chunk: HostRunChunk) => {
        if (asyncStreamError !== null) {
          // The stream already emitted an async 'error' — the pipe is gone. Throw
          // through (the same contract as a sync write failure) so the core flips
          // its passthrough-broken flag instead of writing to a broken stream.
          throw new Error(asyncStreamError);
        }
        const toStderr = json || chunk.stream === 'stderr';
        const streamName: 'stdout' | 'stderr' = toStderr ? 'stderr' : 'stdout';
        // Skip a stream already known broken (honest degradation; passthroughError
        // already records the failure) — never queue a fresh write onto a dead pipe.
        if (toStderr ? stderrBroken : stdoutBroken) return;
        const stream = toStderr ? process.stderr : process.stdout;
        pendingWrites += 1;
        try {
          stream.write(chunk.text, (err) => {
            if (err) recordStreamError(streamName)(err);
            settleWrite();
          });
        } catch (err) {
          // Rare synchronous throw (e.g. write-after-end): settle the counter, then
          // throw through so the core flips its passthrough-broken flag (F-008).
          settleWrite();
          throw err instanceof Error ? err : new Error(`host_run passthrough write failed: ${String(err)}`);
        }
      };

      // F-020 / F-023 / F-024: gated, SETTLE-AWARE stderr diagnostics that also join
      // the pendingWrites accounting. Never write to a stderr already known broken
      // (avoids a late async EPIPE 'error' firing with no listener). When we DO
      // write, the promise resolves on the write CALLBACK and the SAME callback
      // decrements the shared counter — so both the per-call await (F-023) AND the
      // unified drainPending() (F-024) cover this write. The crux F-023 case is a
      // quiet text-mode run whose stderr is already closed, where this final usage
      // line is the FIRST stderr write (stderrBroken never opened, nothing skipped
      // it). A callback/synchronous error folds into the SAME broken/async-error
      // state (recordStreamError via onStderrError) and is swallowed — best-effort
      // diagnostics must never turn a completed run into a crash (F-008 contract).
      const emitStderr = (text: string): Promise<void> => {
        if (stderrBroken) return Promise.resolve();
        return new Promise<void>((resolve) => {
          pendingWrites += 1;
          try {
            process.stderr.write(text, (err) => {
              if (err) onStderrError(err);
              settleWrite();
              resolve();
            });
          } catch (err) {
            // Rare synchronous throw — flip broken state and settle.
            onStderrError(err);
            settleWrite();
            resolve();
          }
        });
      };

      // F-020: attach the async stream-error guards for the DURATION of the run,
      // then remove exactly them in the finally below (never removeAllListeners).
      process.stdout.on('error', onStdoutError);
      process.stderr.on('error', onStderrError);
      let result: HostRunResult;
      try {
        let run = submitted;
        let afterSequence = 0;
        let managedPassthroughError: string | null = null;
        let outputTruncated = false;
        const deliverNewFrames = (): void => {
          let hasMore = true;
          while (hasMore) {
            const output = readManagedHostRunOutput({ root: ctx.root, runId: submitted.runId, afterSequence });
            afterSequence = output.nextSequence;
            hasMore = output.hasMore;
            outputTruncated ||= output.truncated;
            for (const frame of output.frames) {
              if (managedPassthroughError) break;
              try {
                passthrough({ stream: frame.stream, text: frame.text });
              } catch (error) {
                managedPassthroughError = error instanceof Error ? error.message : String(error);
              }
            }
            if (managedPassthroughError) break;
          }
        };
        while (!run.terminal) {
          deliverNewFrames();
          const status = await getManagedHostRunStatus({
            root: ctx.root,
            runId: submitted.runId,
            afterGeneration: run.generation,
            waitMs: 30_000,
          });
          run = status.run;
        }
        deliverNewFrames();
        result = projectManagedTerminalResult(run, readManagedHostRunResult(ctx.root, submitted.runId));
        if (!result.passthroughError && managedPassthroughError) result.passthroughError = managedPassthroughError;

        // F-020: an async stream 'error' that landed AFTER the final chunk (so the
        // sink's throw-through never ran) is still surfaced honestly here — merge
        // the handler-observed async failure with the core-reported sink failure.
        const passthroughError = result.passthroughError ?? asyncStreamError;

        const usageLine = formatUsageLine(result);

        // F-008 / F-020: honest degradation notice — the run completed, but live
        // output delivery broke partway (text mode prints it; json mode carries the
        // field).
        const passthroughWarning = passthroughError
          ? `host_run warning: live output passthrough failed (${passthroughError}); output delivery degraded but the run and usage recording completed\n`
          : null;
        const truncatedWarning = outputTruncated
          ? 'host_run warning: live output truncated=true (8 MiB retention ceiling); omitted tail is not promised\n'
          : null;

        if (json) {
          // Machine mode: the full host transcript already streamed to stderr; the
          // JSON payload (exitCode, usage, refusal, bounded stdout tail, truncated)
          // is the single stdout line. The engine prints it; exitCode is a field.
          // F-023: await the write so it settles (and any EPIPE 'error' fires)
          // while our stderr listener is still attached (finally removes it).
          await emitStderr(`${usageLine}\n`);
          return {
            schemaVersion: 'lattice.host_run.v1',
            host: result.host,
            storyId: result.storyId,
            phase: result.phase,
            agentType: result.agentType,
            spawned: result.spawned,
            blocked: result.blocked,
            refusalReason: result.refusalReason,
            liveRuns: result.liveRuns,
            exitCode: result.exitCode,
            timedOut: result.timedOut,
            stdout: result.stdout,
            stderr: result.stderr,
            usage: result.usageSummary,
            passthroughError,
            runId: submitted.runId,
            managed: true,
            truncated: outputTruncated,
          };
        }

        // Text mode. Host output already streamed live through the passthrough, so
        // the handler never re-prints it (no double-print). F-023: await every
        // diagnostic write so it settles while our stderr listener is still
        // attached (finally removes it) — the crux case is this quiet-run usage
        // line being the FIRST stderr write onto an already-closed stderr.
        if (passthroughWarning) await emitStderr(passthroughWarning);
        if (truncatedWarning) await emitStderr(truncatedWarning);
        if (result.blocked || result.exitCode !== 0 || result.timedOut) {
          // Failure / refusal: usage/refusal line to stderr, then throw so the
          // process exits nonzero (engine forces exit 0 on a normal return).
          await emitStderr(`${usageLine}\n`);
          if (result.blocked) {
            throw new Error(`host_run refused (${result.refusalReason}); no host was launched`);
          }
          const timeoutNote = result.timedOut ? ' (timed out)' : '';
          throw new Error(`host_run: ${result.host} exited ${result.exitCode}${timeoutNote}`);
        }

        // Success: output already streamed; nothing left to print. F-023: await
        // the final usage-line write so a late EPIPE fires under our listener.
        await emitStderr(`${usageLine}\n`);
        return '';
      } finally {
        // F-024: await all in-flight passthrough + diagnostic writes (bounded by the
        // defensive DRAIN_CAP_MS) BEFORE removing the error listeners, so a late
        // EPIPE from the FINAL chunk(s) fires while our named 'error' listeners are
        // still attached. Resolves immediately when nothing is pending.
        await drainPending();
        // F-020: listener hygiene — remove exactly our two listeners, leaving any
        // other listeners on these shared streams untouched.
        process.stdout.removeListener('error', onStdoutError);
        process.stderr.removeListener('error', onStderrError);
      }
    },

    async host_run_status(args: HostRunStatusCommandArgs) {
      const runId = normalizeString(args.runId);
      if (!runId) throw new Error('host_run_status: --runId is required');
      const afterGeneration = optionalNonnegativeInteger(
        'host_run_status',
        'afterGeneration',
        args.afterGeneration,
      );
      const afterSequence = optionalNonnegativeInteger('host_run_status', 'afterSequence', args.afterSequence);
      const waitMs = optionalNonnegativeInteger('host_run_status', 'waitMs', args.waitMs, 30_000);
      const status = await getManagedHostRunStatus({
        root: ctx.root,
        runId,
        afterGeneration,
        waitMs,
        maxWaitMs: options.statusWaitCapMs,
      });
      const output = readManagedHostRunOutput({
        root: ctx.root,
        runId,
        afterSequence: afterSequence ?? 0,
      });
      if (wantsJson(args)) return { ...status, output };
      const terminal = status.run.terminal
        ? ` terminal=${status.run.terminal.state}:${status.run.terminal.reason}`
        : '';
      const receipt = status.receipt ? ` receiptId=${status.receipt.receiptId}` : '';
      return `${status.run.runId} state=${status.run.state} generation=${status.run.generation} deadlineAt=${status.run.deadlineAt} workerHeartbeatAt=${status.run.workerHeartbeatAt ?? 'none'} providerProgressMode=${status.run.providerProgressMode} lastProviderProgressAt=${status.run.lastProviderProgressAt ?? 'none'} replacementSafe=${status.run.replacementSafe}${terminal}${receipt}`;
    },

    async host_run_cancel(args: HostRunCancelCommandArgs) {
      const runId = normalizeString(args.runId);
      if (!runId) throw new Error('host_run_cancel: --runId is required');
      const run = await cancelManagedHostRun({
        root: ctx.root,
        runId,
        reason: normalizeString(args.reason) || undefined,
      });
      if (wantsJson(args)) return { schemaVersion: 'lattice.host_run_cancel.v1', run };
      return `${run.runId} state=${run.state} cancelRequestedAt=${run.cancelRequestedAt ?? 'none'} replacementSafe=${run.replacementSafe}`;
    },

    async host_run_worker(args: HostRunWorkerCommandArgs): Promise<string> {
      const runId = normalizeString(args.runId);
      if (!runId) throw new Error('host_run_worker: --runId is required');
      await runManagedHostRunWorker({ root: ctx.root, runId });
      return '';
    },
  };
}
/**
 * Canonical, ledger-independent provider-process capacity registry.
 *
 * Admission is an atomic exclusive create of one of a fixed set of numbered
 * slots. Usage accounting may be disabled; this registry never is. A recorded
 * live pid is never reclaimed because of age alone, and release is guarded by
 * the acquire-minted ownership token.
 */

import { randomUUID } from 'node:crypto';
import {
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  statSync,
  unlinkSync,
  renameSync,
  writeFileSync,
} from 'node:fs';
import { hostname } from 'node:os';
import { dirname, join } from 'node:path';
import {
  acquireMkdirLock,
  type ExistingMkdirLockSnapshot,
  type ExistingMkdirLockState,
} from './mkdir-lock.js';
import { resolveCanonicalRuntimeProjectRoot } from './runtime-artifact-registry.js';

const PROVIDER_PROCESS_SLOTS_RELATIVE = join('.lattice', 'runtime', 'provider-process-slots');
export const PROVIDER_PROCESS_MAX_CONCURRENT_DEFAULT = 4;
export const PROVIDER_PROCESS_SLOT_STALE_MS_DEFAULT = 6 * 60 * 60 * 1000;

export interface ProviderProcessLiveDescriptor {
  pid: number;
  startedAt: string;
  host: string;
  storyId: string | null;
  agentType: string;
}

export interface ProviderProcessSlotMeta extends ProviderProcessLiveDescriptor {}

export interface ProviderProcessSlotFileMeta extends ProviderProcessSlotMeta {
  token: string;
  providerPid?: number;
  providerPgid?: number;
  providerSpawnedAt?: string;
  providerStartFingerprint?: string;
  providerProcessGroupIsolated?: boolean;
}

export interface AcquiredProviderProcessSlot {
  file: string;
  token: string;
}

export interface ProviderRegistryLockTiming {
  deadlineMs?: number;
  staleMs?: number;
  pollMs?: number;
}

export interface ProviderRegistryMutationOps {
  unlink(file: string): void;
}

const DEFAULT_PROVIDER_REGISTRY_MUTATION_OPS: ProviderRegistryMutationOps = {
  unlink: unlinkSync,
};

type SlotOccupant =
  | { state: 'valid'; pid: number; token: string | null; meta: Record<string, unknown> }
  | { state: 'corrupt'; identity: string }
  | { state: 'missing' };

function corruptSlotIdentity(file: string, raw: string): string {
  try {
    const stat = statSync(file);
    return `${stat.dev}:${stat.ino}:${stat.size}:${stat.mtimeMs}:${raw}`;
  } catch (error) {
    return `unstatable:${(error as NodeJS.ErrnoException).code ?? 'unknown'}:${raw}`;
  }
}

function ownString(value: Record<string, unknown>, key: string): string | null {
  if (!Object.prototype.hasOwnProperty.call(value, key)) return null;
  return typeof value[key] === 'string' ? value[key] as string : null;
}

function ownNumber(value: Record<string, unknown>, key: string): number | null {
  if (!Object.prototype.hasOwnProperty.call(value, key)) return null;
  return typeof value[key] === 'number' && Number.isInteger(value[key]) ? value[key] as number : null;
}

function readSlotOccupant(file: string): SlotOccupant {
  let raw: string;
  try {
    raw = readFileSync(file, 'utf8');
  } catch (error) {
    return (error as NodeJS.ErrnoException).code === 'ENOENT'
      ? { state: 'missing' }
      : { state: 'corrupt', identity: corruptSlotIdentity(file, '') };
  }
  try {
    const parsed = JSON.parse(raw) as unknown;
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
      return { state: 'corrupt', identity: corruptSlotIdentity(file, raw) };
    }
    const meta = parsed as Record<string, unknown>;
    const pid = ownNumber(meta, 'pid');
    if (pid === null) return { state: 'corrupt', identity: corruptSlotIdentity(file, raw) };
    return { state: 'valid', pid, token: ownString(meta, 'token'), meta };
  } catch {
    return { state: 'corrupt', identity: corruptSlotIdentity(file, raw) };
  }
}

function sameSlotOccupant(left: SlotOccupant, right: SlotOccupant): boolean {
  if (left.state !== right.state) return false;
  if (left.state === 'valid' && right.state === 'valid') {
    return left.pid === right.pid && left.token === right.token;
  }
  if (left.state === 'corrupt' && right.state === 'corrupt') {
    return left.identity === right.identity;
  }
  return true;
}

function pidAlive(pid: number): boolean {
  if (!Number.isInteger(pid) || pid <= 0) return false;
  try {
    process.kill(pid, 0);
    return true;
  } catch (error) {
    return (error as NodeJS.ErrnoException).code === 'EPERM';
  }
}

function processGroupAlive(pgid: number): boolean {
  if (!Number.isInteger(pgid) || pgid <= 0 || process.platform === 'win32') return false;
  try {
    process.kill(-pgid, 0);
    return true;
  } catch (error) {
    return (error as NodeJS.ErrnoException).code === 'EPERM';
  }
}

function slotReclaimable(occupant: SlotOccupant, file: string, now: number, staleMs: number): boolean {
  if (occupant.state === 'missing') return true;
  if (occupant.state === 'valid') {
    const isolated = occupant.meta.providerProcessGroupIsolated === true;
    const providerPgid = ownNumber(occupant.meta, 'providerPgid');
    // Once the admission has transferred to an isolated provider group, the
    // group—not the supervising worker—is the capacity owner. A crashed worker
    // may leave children alive, so reclaim only after the exact PGID disappears.
    if (isolated && providerPgid !== null && processGroupAlive(providerPgid)) return false;
    return !pidAlive(occupant.pid);
  }
  try {
    const ageMs = now - statSync(file).mtimeMs;
    return !Number.isFinite(ageMs) || ageMs > staleMs;
  } catch {
    // Fail closed: an existing slot we cannot stat still occupies capacity.
    return false;
  }
}

export function providerProcessSlotsDir(root: string): string {
  return join(resolveCanonicalRuntimeProjectRoot(root), PROVIDER_PROCESS_SLOTS_RELATIVE);
}

export function resolveProviderProcessMaxConcurrent(env: NodeJS.ProcessEnv): number {
  const raw = env.LATTICE_HOST_RUN_MAX_CONCURRENT;
  if (typeof raw !== 'string' || raw.trim().length === 0) return PROVIDER_PROCESS_MAX_CONCURRENT_DEFAULT;
  const value = Number(raw.trim());
  return Number.isFinite(value) && Number.isInteger(value) && value > 0
    ? value
    : PROVIDER_PROCESS_MAX_CONCURRENT_DEFAULT;
}

export function resolveProviderProcessSlotStaleMs(env: NodeJS.ProcessEnv): number {
  const raw = env.LATTICE_HOST_RUN_SLOT_STALE_MS;
  if (typeof raw !== 'string' || raw.trim().length === 0) return PROVIDER_PROCESS_SLOT_STALE_MS_DEFAULT;
  const value = Number(raw.trim());
  return Number.isFinite(value) && value > 0 ? value : PROVIDER_PROCESS_SLOT_STALE_MS_DEFAULT;
}

export function writeProviderProcessSlotExclusive(
  file: string,
  meta: ProviderProcessSlotFileMeta,
): boolean {
  try {
    writeFileSync(file, JSON.stringify(meta), { encoding: 'utf8', flag: 'wx', mode: 0o600 });
    return true;
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'EEXIST') return false;
    throw error;
  }
}

function scanLiveProviderProcessSlotsUnlocked(
  dir: string,
  now: number,
  staleMs: number,
): ProviderProcessLiveDescriptor[] {
  let entries: string[];
  try {
    entries = readdirSync(dir);
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return [];
    const code = (error as NodeJS.ErrnoException).code ?? 'unknown';
    const detail = error instanceof Error ? error.message : String(error);
    throw new Error(`provider-process-registry slots directory unreadable (${code}): ${detail}`);
  }
  const live: ProviderProcessLiveDescriptor[] = [];
  for (const name of entries) {
    if (!name.endsWith('.json')) continue;
    const file = join(dir, name);
    const occupant = readSlotOccupant(file);
    if (slotReclaimable(occupant, file, now, staleMs)) {
      if (occupant.state !== 'missing' && sameSlotOccupant(readSlotOccupant(file), occupant)) {
        try { unlinkSync(file); } catch { /* racing reclaim is benign */ }
      }
      continue;
    }
    if (occupant.state !== 'valid') continue;
    live.push({
      pid: occupant.pid,
      startedAt: ownString(occupant.meta, 'startedAt') ?? '',
      host: ownString(occupant.meta, 'host') ?? '',
      storyId: ownString(occupant.meta, 'storyId'),
      agentType: ownString(occupant.meta, 'agentType') ?? '',
    });
  }
  return live;
}

function currentProcessStartTimeMs(): number {
  return Math.floor(Date.now() - process.uptime() * 1_000);
}

function sameProcessStart(left: number | undefined, right: number | undefined): boolean {
  if (left === undefined || right === undefined) return true;
  return Math.abs(left - right) <= 2_000;
}

// B-137a:F-124 — used at the classifyExistingLock wiring below, so NOT dead
// code; the `export` was the only dead part (no importer anywhere in
// packages/main/src or scripts). Narrowed to module-private.
function classifyProviderRegistryLock(snapshot: ExistingMkdirLockSnapshot): ExistingMkdirLockState {
  const holder = snapshot.holder;
  if (!holder || holder.hostname !== hostname()) return 'unknown';
  if (!Number.isInteger(holder.pid) || holder.pid <= 0) return 'unknown';
  try {
    process.kill(holder.pid, 0);
  } catch (error) {
    const code = (error as NodeJS.ErrnoException).code;
    if (code === 'ESRCH') return 'stale';
    if (code !== 'EPERM') return 'unknown';
  }
  if (
    holder.pid === process.pid
    && !sameProcessStart(holder.processStartTimeMs, currentProcessStartTimeMs())
  ) return 'stale';
  return 'active';
}

function withProviderRegistryLock<T>(
  dir: string,
  fn: () => T,
  timing: ProviderRegistryLockTiming = {},
): T {
  const lock = acquireMkdirLock(`${dir}.lock`, {
    label: 'provider-process-registry',
    deadlineMs: timing.deadlineMs ?? 30_000,
    staleMs: timing.staleMs ?? 10_000,
    pollMs: timing.pollMs ?? 10,
    requireHolderToken: true,
    classifyExistingLock: classifyProviderRegistryLock,
    holderInfo: {
      pid: process.pid,
      hostname: hostname(),
      command: 'provider-process-registry mutation',
      acquiredAt: new Date().toISOString(),
      lockId: randomUUID(),
      processStartTimeMs: currentProcessStartTimeMs(),
    },
  });
  try {
    return fn();
  } finally {
    lock.release();
  }
}

export function scanLiveProviderProcessSlots(
  dir: string,
  now: number,
  staleMs: number,
  lockTiming: ProviderRegistryLockTiming = {},
): ProviderProcessLiveDescri

ptor[] {
  return withProviderRegistryLock(dir, () => scanLiveProviderProcessSlotsUnlocked(dir, now, staleMs), lockTiming);
}

export function acquireProviderProcessSlot(
  dir: string,
  cap: number,
  staleMs: number,
  now: number,
  meta: ProviderProcessSlotMeta,
  lockTiming: ProviderRegistryLockTiming = {},
): AcquiredProviderProcessSlot | null {
  mkdirSync(dir, { recursive: true });
  const boundedCap = Number.isFinite(cap) && Number.isInteger(cap) && cap > 0
    ? cap
    : PROVIDER_PROCESS_MAX_CONCURRENT_DEFAULT;
  return withProviderRegistryLock(dir, () => {
    const live = scanLiveProviderProcessSlotsUnlocked(dir, now, staleMs);
    if (live.length >= boundedCap) return null;
    const token = randomUUID();
    const record: ProviderProcessSlotFileMeta = { ...meta, token };
    for (let index = 0; index < boundedCap; index += 1) {
      const file = join(dir, `slot-${index}.json`);
      if (writeProviderProcessSlotExclusive(file, record)) return { file, token };
      const judged = readSlotOccupant(file);
      if (!slotReclaimable(judged, file, now, staleMs)) continue;
      if (judged.state !== 'missing') {
        if (!sameSlotOccupant(readSlotOccupant(file), judged)) continue;
        try { unlinkSync(file); } catch { /* exclusive recreate decides the winner */ }
      }
      if (writeProviderProcessSlotExclusive(file, record)) return { file, token };
    }
    return null;
  }, lockTiming);
}

export function releaseProviderProcessSlot(
  file: string | null,
  token: string | null,
  lockTiming: ProviderRegistryLockTiming = {},
  mutationOps: ProviderRegistryMutationOps = DEFAULT_PROVIDER_REGISTRY_MUTATION_OPS,
): void {
  if (!file || !token) return;
  const dir = dirname(file);
  withProviderRegistryLock(dir, () => {
    const occupant = readSlotOccupant(file);
    if (occupant.state !== 'valid' || occupant.token !== token) return;
    mutationOps.unlink(file);
  }, lockTiming);
}

/**
 * B-137a F-119: BEST-EFFORT release for `finally` blocks.
 *
 * Two correct-but-opposed requirements meet here:
 *   1. A release failure must be OBSERVABLE, not a silent capacity leak --
 *      releaseProviderProcessSlot therefore throws, and a registry smoke pins
 *      that ("slot unlink mutation failure must be observable instead of
 *      silently leaking capacity").
 *   2. Every production release happens in a bare `finally` (host-run,
 *      autopilot-executor, codex-review-leaf, provider-process-admission), and
 *      a throw from `finally` REPLACES the in-flight exception -- hiding the
 *      real provider failure -- or turns a successful run into a hard error.
 *      host-run.ts's original releaseSlot wrapped its body in try/catch for
 *      exactly this reason; a refactor dropped that.
 *
 * Swallowing inside the primitive would satisfy (2) by destroying (1). So the
 * primitive keeps throwing and `finally` callers use this wrapper, which
 * reports the failure through onFailure instead of hijacking control flow.
 * Capacity is still reclaimable: pid-death detection and the orphan backstop
 * recover a leaked slot, whereas a masked exception is unrecoverable.
 */
export function releaseProviderProcessSlotBestEffort(
  file: string | null,
  token: string | null,
  onFailure: (error: unknown) => void = defaultReleaseFailureReporter,
  lockTiming: ProviderRegistryLockTiming = {},
  mutationOps: ProviderRegistryMutationOps = DEFAULT_PROVIDER_REGISTRY_MUTATION_OPS,
): void {
  try {
    releaseProviderProcessSlot(file, token, lockTiming, mutationOps);
  } catch (error) {
    // Never rethrow: this runs in finally. Reporting must not fail either.
    try {
      onFailure(error);
    } catch { /* a broken reporter must not mask the caller's exception */ }
  }
}

function defaultReleaseFailureReporter(error: unknown): void {
  const detail = error instanceof Error ? error.message : String(error);
  process.stderr.write(
    `⚠ provider process slot release failed (capacity is reclaimed by pid-death / orphan backstop): ${detail}\n`,
  );
}

export function transferProviderProcessSlotToProvider(
  file: string | null,
  token: string | null,
  identity: {
    pid: number;
    pgid: number | null;
    spawnedAt: string;
    startFingerprint: string | null;
    processGroupIsolated: boolean;
  },
  lockTiming: ProviderRegistryLockTiming = {},
): boolean {
  if (!file || !token) return false;
  if (
    !Number.isInteger(identity.pid) || identity.pid <= 0
    || !identity.processGroupIsolated
    || !Number.isInteger(identity.pgid) || (identity.pgid ?? 0) <= 0
  ) return false;
  const dir = dirname(file);
  return withProviderRegistryLock(dir, () => {
    const occupant = readSlotOccupant(file);
    if (occupant.state !== 'valid' || occupant.token !== token) return false;
    const next: ProviderProcessSlotFileMeta = {
      ...(occupant.meta as unknown as ProviderProcessSlotFileMeta),
      pid: identity.pid,
      providerPid: identity.pid,
      providerPgid: identity.pgid!,
      providerSpawnedAt: identity.spawnedAt,
      providerStartFingerprint: identity.startFingerprint ?? undefined,
      providerProcessGroupIsolated: true,
      token,
    };
    const temporary = `${file}.${token}.transfer`;
    writeFileSync(temporary, JSON.stringify(next), { encoding: 'utf8', flag: 'wx', mode: 0o600 });
    try {
      // Registry lock + exact token check makes this replacement ownership-safe.
      renameSync(temporary, file);
    } finally {
      try { unlinkSync(temporary); } catch { /* rename already consumed it */ }
    }
    return true;
  }, lockTiming);
}

export type ProviderExecutionSurfaceStatus =
  | 'managed'
  | 'admission_only'
  | 'adapter_only'
  | 'readiness_probe'
  | 'legacy_unmanaged';

export interface ProviderExecutionSurface {
  path: string;
  status: ProviderExecutionSurfaceStatus;
  admissionOwner: string | null;
  note: string;
}

/**
 * Conservative source classifier used by the contract smoke. Any production
 * file that imports a provider adapter, is itself an adapter, or combines a
 * child-process API with provider vocabulary must have an explicit inventory
 * row. False positives are classified, never silently excluded, so adding a
 * new direct provider spawn in a new file makes the contract fail closed.
 */
export function isProviderExecutionSurfaceCandidate(relativePath: string, source: string): boolean {
  if (!relativePath.endsWith('.ts')) return false;
  if (/(?:^|\/)(?:tasks|tests|generated)(?:\/|$)/.test(relativePath)) return false;
  if (relativePath === 'core/provider-process-registry.ts') return false;
  if (/^providers\/(?:codex-cli|claude-cli|gemini-cli)\.ts$/.test(relativePath)) return true;
  if (/providers\/(?:codex-cli|claude-cli|gemini-cli)\.js/.test(source)) return true;
  if (/\brunHostRun\s*\(/.test(source)) return true;
  // B-137a: strip documentation filename references before the provider-word
  // scan. The words are matched case-insensitively, so a prose citation of
  // "CLAUDE.md" (the project convention doc, referenced by many core modules)
  // read as a provider reference: any file that both used child_process for git
  // and cited that doc became an "unclassified provider execution surface".
  // scope-contract.ts tripped exactly this way on a comment citing the handler
  // convention -- a docs citation, not a provider workload. Several already
  // inventoried files (audit-scan, audit-trigger, rollout-check,
  // runtime-environment-checks) match for the same non-reason. Stripping only
  // "<provider>.md" filenames keeps every real provider reference intact,
  // including CLAUDE_CLI, claudeCli, 'claude' and providers/claude-cli.js.
  const withoutDocReferences = source.replace(/\b(?:codex|claude|agy|gemini|antigravity)\.md\b/gi, '');
  // B-137a: the provider word no longer requires a trailing \b. The old
  // /\bclaude\b/i missed identifier forms entirely -- `claudeCli`, `CLAUDE_CLI`,
  // `codexRunner` all failed to match, because \b does not break between two
  // word characters or before `_`. A file spawning a provider through such an
  // identifier was therefore invisible to this tripwire (verified against the
  // pre-change regex). A leading boundary is kept so unrelated substrings do not
  // match, but the tail is now open so identifier and member forms are caught.
  return /node:child_process/.test(source)
    && /\b(?:codex|claude|agy|gemini|antigravity)/i.test(withoutDocReferences);
}

